def add_matrices(A, B):
    return [[A[i][j] + B[i][j] for j in range(len(A[0]))] for i in range(len(A))]

def multiply_matrices(A, B):
    rA, cA, cB = len(A), len(A[0]), len(B[0])
    res = [[0] * cB for _ in range(rA)]
    for i in range(rA):
        for j in range(cB):
            for k in range(cA):
                res[i][j] += A[i][k] * B[k][j]
    return res

def is_symmetric(matrix):
    n = len(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class SinglyLinkedList:
    def __init__(self):
        self.head = None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        curr = self.head
        while curr.next:
            curr = curr.next
        curr.next = new_node

class DNode:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, data):
        new_node = DNode(data)
        if not self.head:
            self.head = self.tail = new_node
        else:
            self.tail.next = new_node
            new_node.prev = self.tail
            self.tail = new_node

class CircularLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            new_node.next = self.head
            return
        curr = self.head
        while curr.next != self.head:
            curr = curr.next
        curr.next = new_node
        new_node.next = self.head

class Stack:
    def __init__(self):
        self._items = []
    def push(self, val): self._items.append(val)
    def pop(self): return self._items.pop() if self._items else None
    def is_empty(self): return len(self._items) == 0

def is_balanced(expr):
    stk = Stack()
    mapping = {')': '(', '}': '{', ']': '['}
    for ch in expr:
        if ch in mapping.values(): stk.push(ch)
        elif ch in mapping.keys():
            if stk.is_empty() or stk.pop() != mapping[ch]: return False
    return stk.is_empty()

